-- food menu snapshots, batch 5 (25 menus)
with target as (
  select slug from venues where slug = 'the-butchers-club-steakhouse' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'The Butchers Club Steakhouse menu', 1, 'draft', 'partial', 'https://www.thebutchersbali.com/others-meat', 'Official The Butchers Club Steakhouse menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '2299c6308dc7c434c9485e3731586abf88395d22bcbdf27a380230f212b73dc1', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Others Meat', 0)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Others Meat', 'Slow cooked Lamb Shank', 'Sweet potato mash, steamed vegetables, green peas and home made Tzatziki sauce.', 285000, 'IDR', 0), ('Others Meat', 'katsu chicken', 'Breaded chicken breast topped with mozzarella & napoletana sauce. Served with fries and coleslaw.', 120000, 'IDR', 1), ('Others Meat', 'Traditional fish & chips', '200 gr panko breaded barramundi served with French fries and tartar sauce.', 132000, 'IDR', 2), ('Others Meat', 'Peri peri bbq chicken', 'Lemon, garlic, rosemary marinated half grilled chicken. Served with grilled corn, sauteed seasonal vegetables & peri peri sauce.', 125000, 'IDR', 3), ('Others Meat', 'Pan fried barramundi', 'Skin off Barramundi, sauteed summer vegetable with lemon butter sauce', 120000, 'IDR', 4)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

