join (values ('Bebek Khas Ubud & Hidangan Favorit Keluarga', 'Bebek Goreng Tepi Sawah (Crispy Duck)', 'Bebek setengah ekor digoreng hingga super renyah dan garing, disajikan dengan nasi putih, urapan sayur, dan trio sambal khas Bali.', 179200, 'IDR', 0), ('Bebek Khas Ubud & Hidangan Favorit Keluarga', 'Bebek Bakar Tepi Sawah', 'Bebek setengah ekor dibakar dengan bumbu kecap manis khas, menghasilkan daging yang juicy dengan aroma bakaran yang menggugah selera.', 179200, 'IDR', 1), ('Bebek Khas Ubud & Hidangan Favorit Keluarga', 'Bebek Betutu Tepi Sawah', 'Bebek khas bumbu Bali (basa genep) yang dimasak perlahan hingga bumbu meresap sempurna, disajikan dengan urapan sayur.', 179200, 'IDR', 2), ('Bebek Khas Ubud & Hidangan Favorit Keluarga', 'Nasi Goreng Bebek Tepi Sawah', 'Nasi goreng kampung khas, disajikan dengan ¼ ekor bebek, telur mata sapi, dan acar — comfort food yang tetap berkelas.', 100000, 'IDR', 3), ('Pilihan Menu Lain', 'Ayam Goreng / Ayam Betutu / Ayam Bakar Taliwang', 'Ragam olahan ayam dengan bumbu Nusantara — dari goreng renyah, betutu kaya rempah, hingga bakar taliwang yang pedas menggoda.', null, null, 0), ('Pilihan Menu Lain', 'Gurame Asam Manis / Gurame Bakar / Calamary Ring', 'Pilihan ikan dan seafood untuk pecinta hidangan laut, cocok untuk sharing bersama keluarga.', null, null, 1), ('Pilihan Menu Lain', 'Sate Lilit Ayam', 'Sate khas Bali dari daging yang dicincang halus dengan bumbu basa genep, dililit pada batang serai — aromatik dan juicy.', 45000, 'IDR', 2), ('Pilihan Menu Lain', 'Sop Garang Asam Iga / Sop Buntut / Soto Ayam / Tom Yam Gong', 'Pilihan sup hangat yang menguatkan suasana: dari rasa segar asam, gurih kaldu iga, hingga Tom Yam dengan sentuhan Asia.', null, null, 3), ('Pilihan Menu Lain', 'Pisang Goreng Tepi Sawah & Dessert', 'Pisang goreng dengan es krim, aneka dessert manis, serta minuman segar seperti kelapa muda dan jus buah tropis.', null, null, 4), ('Pilihan Menu Lain', 'Kopi Luwak & Minuman Spesial', 'Nikmati kopi luwak dan minuman spesial lainnya sambil memandangi sawah — penutup yang sempurna setelah menyantap bebek crispy.', null, null, 5), ('Catatan harga', 'Kisaran harga menu bebek', 'Rp 160.000 – Rp 180.000 per porsi', null, null, 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

