with target as (
  select slug from venues where slug = 'fair-warung-bale' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Full Menu', 1, 'draft', 'partial', 'https://fairwarungbale.shop', 'Official Fair Warung Balé menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '4f8a9b4160888df11ab397d49e2194faddc4c33b7fed5e1116203e506e41d062', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Featured Choices', 0)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Featured Choices', 'Cashew Chicken Curry', 'A spicy chicken curry featuring cashews, known for its rich flavors and tender texture.', 85000, 'IDR', 0), ('Featured Choices', 'Variety Platter', 'An assortment of beautifully presented dishes, a treat for both the eyes and the taste buds.', 100000, 'IDR', 1), ('Featured Choices', 'Chicken Satay', 'Grilled chicken skewers served with peanut sauce.', 50000, 'IDR', 2), ('Featured Choices', 'Fried Fish', 'Fresh, succulent fried fish served with traditional sauces.', 70000, 'IDR', 3), ('Featured Choices', 'Vegetarian Curry', 'A hearty vegetarian curry bursting with flavor.', 80000, 'IDR', 4), ('Featured Choices', 'Fresh Coconut', 'Refreshing drink served directly from the coconut.', 30000, 'IDR', 5), ('Featured Choices', 'Lassi', 'Smooth, creamy yogurt drink.', 40000, 'IDR', 6), ('Featured Choices', 'Salty Tomato Juice', 'Chilled tomato juice with a twist of salt.', 25000, 'IDR', 7), ('Featured Choices', 'Onion Rings', 'Crispy battered onion rings served as a side.', 20000, 'IDR', 8)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

update menus set status = 'source_snapshot', source_snapshot_published_at = '2026-08-25T01:47:06+00:00'::timestamptz
where status = 'draft'
  and completeness = 'partial'
  and verified_at is null
  and content_digest is not null
  and expires_at > now()
  and created_at >= '2026-08-25T01:47:06+00:00'::timestamptz
  and exists (select 1 from menu_sections s join menu_items it
              on it.section_id = s.id and it.menu_id = s.menu_id
              where s.menu_id = menus.id);
